UPDATE t_feedback_distribution_batch SET batch_status='COMPENSATION_FAILED',
    compensation_attempts=#{attempts},failure_reason=#{reason},next_compensation_at=DATE_ADD(NOW(3),INTERVAL #{delay} SECOND)
    WHERE id=#{id}

mapper.select:
SELECT id FROM t_feedback_distribution_batch
    WHERE batch_status IN ('COMPENSATING','COMPENSATION_FAILED')
    AND (next_compensation_at IS NULL OR next_compensation_at<=NOW(3)) ORDER BY id LIMIT #{limit}
